-- Migration 33: branded ticket tiers, the host trust card, and an email retry fix.
--  1. Ticket types carry a tier (General, Early bird, VIP, VVIP, Backstage, Student, Table, Group), an optional organiser
--     accent colour, a design style and up to six short perks. Purely presentational: price and stock rules are unchanged.
--  2. host_reputation(host): what a buyer may know before trusting a host, counted only over plans the viewer can see.
--  3. email_worker_done: a message that has used its 5 attempts is marked failed at once (it previously stayed pending,
--     and the cron job only calls the worker for rows with attempts left, so it was never closed).

-- ---------------------------------------------------------------- 1. ticket tiers
create or replace function public.perks_ok(p text[]) returns boolean
language sql immutable set search_path = '' as $$
  select coalesce(cardinality(p), 0) <= 6 and coalesce((select bool_and(char_length(btrim(x)) between 1 and 40) from unnest(p) x), true);
$$;
alter table public.ticket_types add column if not exists tier text not null default 'general'
  check (tier in ('general', 'early_bird', 'vip', 'vvip', 'backstage', 'student', 'table', 'group'));
alter table public.ticket_types add column if not exists accent text check (accent is null or accent ~ '^#[0-9a-fA-F]{6}$');
alter table public.ticket_types add column if not exists design text not null default 'aurora' check (design in ('aurora', 'foil', 'mesh', 'minimal'));
alter table public.ticket_types add column if not exists perks text[] not null default '{}';
alter table public.ticket_types drop constraint if exists ticket_types_perks_ok;
alter table public.ticket_types add constraint ticket_types_perks_ok check (public.perks_ok(perks));
-- Existing names that clearly say VIP / VVIP / early bird get that tier, so current events look right straight away.
update public.ticket_types set tier = case
    when name ~* '\mvvip\M' then 'vvip' when name ~* '\mvip\M' then 'vip' when name ~* 'early\s*bird' then 'early_bird'
    when name ~* 'backstage' then 'backstage' when name ~* 'student' then 'student' when name ~* '\mtable\M' then 'table'
    when kind = 'group' then 'group' else 'general' end
 where tier = 'general';
grant insert (tier, accent, design, perks) on public.ticket_types to authenticated;
grant update (tier, accent, design, perks) on public.ticket_types to authenticated;

-- ---------------------------------------------------------------- 2. host trust card
create or replace function public.host_reputation(p_host uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare me uuid := auth.uid(); p public.profiles; pol text; n_reviews bigint; avg_rating numeric;
begin
  if me is null then raise exception 'Sign in' using errcode = '28000'; end if;
  if me <> p_host and public.is_blocked(me, p_host) then return null; end if;
  select * into p from public.profiles where id = p_host;
  if not found then return null; end if;
  pol := p.show_followers;
  select count(*), avg(r.rating) into n_reviews, avg_rating
    from public.event_reviews r join public.events e on e.id = r.event_id
   where e.host = p_host and r.status = 'published' and public.can_view_event_id(e.id);
  return jsonb_build_object(
    'member_since', p.created_at,
    'verified', coalesce(p.verified_until > now(), false),
    'plans', (select count(*) from public.events e where e.host = p_host and e.status <> 'draft' and public.can_view_event_id(e.id)),
    'past_plans', (select count(*) from public.events e where e.host = p_host and e.status in ('active', 'completed') and e.starts_at < now() and public.can_view_event_id(e.id)),
    'cancelled', (select count(*) from public.events e where e.host = p_host and e.status = 'cancelled' and public.can_view_event_id(e.id)),
    'people_went', (select count(distinct r.user_id) from public.event_rsvps r join public.events e on e.id = r.event_id
                     where e.host = p_host and r.status = 'going' and e.starts_at < now() and e.status in ('active', 'completed') and public.can_view_event_id(e.id)),
    'reviews', n_reviews,
    'rating', case when n_reviews >= 3 then round(avg_rating, 1) end,
    'approved_for_sales', exists (select 1 from public.events e where e.host = p_host and e.sales_review = 'approved'),
    'followers', case when me = p_host or pol = 'public' or (pol = 'friends' and public.are_friends(me, p_host))
                      then (select count(*) from public.follows where target_type = 'profile' and target_id = p_host) end);
end $$;
revoke execute on function public.host_reputation(uuid) from public, anon;
grant execute on function public.host_reputation(uuid) to authenticated;

-- ---------------------------------------------------------------- 3. email retries end
create or replace function public.email_worker_done(p_key text, p_id bigint, p_status text, p_error text default null) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.email_worker_ok(p_key) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_status not in ('sent', 'pending', 'failed', 'skipped') then raise exception 'bad status'; end if;
  update public.email_outbox
     set status = case when p_status = 'pending' and attempts >= 5 then 'failed' else p_status end,
         last_error = left(p_error, 500), sent_at = case when p_status = 'sent' then now() end
   where id = p_id and status = 'sending';
end $$;
revoke execute on function public.email_worker_done(text, bigint, text, text) from public, anon, authenticated;
-- Rows already stuck that way.
update public.email_outbox set status = 'failed' where status in ('pending', 'sending') and attempts >= 5;

commit;

select item, ok from (values
  ('ticket types carry tier, colour, design and perks', (select count(*) from information_schema.columns where table_name = 'ticket_types' and column_name in ('tier', 'accent', 'design', 'perks')) = 4 and has_column_privilege('authenticated', 'public.ticket_types', 'tier', 'update')),
  ('host card for signed-in members only', has_function_privilege('authenticated', 'public.host_reputation(uuid)', 'execute') and not has_function_privilege('anon', 'public.host_reputation(uuid)', 'execute')),
  ('no email stuck after its last attempt', not exists (select 1 from public.email_outbox where status in ('pending', 'sending') and attempts >= 5))
) as v(item, ok);
